"

# Build per-column unique-element lists (drop NA / empty)
sets <- lapply(df, function(col) {
  vals <- as.character(col)
  vals <- vals[!is.na(vals) & nzchar(vals)]
  unique(vals)
})
cat("Set sizes:\n")
print(sapply(sets, length))
# Universe size and pairwise overlaps for sanity
universe <- unique(unlist(sets))
cat("\nUniverse size:", length(universe), "\n")
cat("\nPairwise intersections:\n")
for (i in seq_along(sets)) {
  for (j in seq_along(sets)) {
    if (j > i) {
      n <- length(intersect(sets[[i]], sets[[j]]))
      cat(sprintf("  %s ∩ %s = %d\n", names(sets)[i], names(sets)[j], n))
    }
  }
}
